"""
    Given a list of command line arguments, quote them so they can be can be
    printed on POSIX
    """
def quotePosix(args: Any) -> object {
    def q(x: Any) -> object {
        if (" " in x) {
            return ("'" + x + "'");
        } else {
            return x;
        }
    }
    return [q(x) for x in args];
}

